CREATE OR REPLACE FUNCTION public.permissoes_do_usuario(p_user_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Somente master revisa permissões' USING ERRCODE='42501'; END IF; RETURN jsonb_build_object('master',public.has_role(p_user_id,'super_admin'),'legado',coalesce((SELECT legado AND revisado_em IS NULL FROM usuario_permissao_estado WHERE user_id=p_user_id),false),'revisado_em',(SELECT revisado_em FROM usuario_permissao_estado WHERE user_id=p_user_id),'revisado_por',(SELECT p.email FROM usuario_permissao_estado e JOIN profiles p ON p.user_id=e.revisado_por WHERE e.user_id=p_user_id),'permissoes',coalesce((SELECT jsonb_agg(permissao ORDER BY permissao) FROM usuario_permissoes WHERE user_id=p_user_id),'[]'::jsonb)); END; $$;
REVOKE ALL ON FUNCTION public.permissoes_do_usuario(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.permissoes_do_usuario(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.usuarios_revisao() RETURNS TABLE(user_id uuid,revisado boolean) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.tem_permissao('usuarios.visualizar') THEN RAISE EXCEPTION 'Acesso não liberado' USING ERRCODE='42501'; END IF; RETURN QUERY SELECT p.user_id,coalesce(e.revisado_em IS NOT NULL,false) FROM profiles p LEFT JOIN usuario_permissao_estado e ON e.user_id=p.user_id; END; $$;
REVOKE ALL ON FUNCTION public.usuarios_revisao() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.usuarios_revisao() TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_permissao_tabela(p_tabela text,p_escrita boolean) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE v text[]; BEGIN
 IF p_escrita THEN
 CASE WHEN p_tabela='metas_loja' THEN v:=ARRAY['metas.alterar']; WHEN p_tabela='portfolios' THEN v:=ARRAY['carteiras.alterar']; WHEN p_tabela IN ('grupos','multilojas_loja') THEN v:=ARRAY['carteiras.alterar']; WHEN p_tabela='ml_settings' THEN v:=ARRAY['integracoes.configurar']; WHEN p_tabela IN ('config_estimativa','benchmark_uplift_full') THEN RETURN public.is_super_admin(); ELSE v:=ARRAY['dados.importar']; END CASE;
 ELSE
 CASE
 WHEN p_tabela IN ('sellers','sellers_pm') THEN SELECT array_agg(chave) INTO v FROM permissao_catalogo WHERE pai IS NULL;
 WHEN p_tabela IN ('sellers_kpi','sellers_kpi_daily','cpp_mensal','cart_cpp_diarizado','cart_cpp_mensal','raw_cpp_mensal','cart_base_vendedores') THEN v:=ARRAY['resumo.visualizar','reputacao.visualizar','preco.visualizar','publicidade.visualizar','promocoes.visualizar','clips.visualizar','logistica.visualizar','qualidade.visualizar','full.visualizar','metas.visualizar','correlacoes.visualizar','alertas.visualizar','carteiras.visualizar','multilojas.visualizar','dados.visualizar'];
 WHEN p_tabela IN ('ml_listings','ml_listings_estado','ml_anuncios','live_listings','gm_live_listings','cart_livelistings','seller_listings_quality') THEN v:=ARRAY['anuncios.visualizar','qualidade.visualizar','full.visualizar','mercado.visualizar','promocoes.visualizar','publicidade.visualizar','logistica.visualizar','carteiras.visualizar','resumo.visualizar'];
 WHEN p_tabela IN ('cdp_mensal','raw_cdp_mensal','cart_cdp_mensal','cart_cdp_diarizado','meli_campaigns','ml_promotions','ml_promotion_items') THEN v:=ARRAY['promocoes.visualizar','resumo.visualizar','carteiras.visualizar','multilojas.visualizar','dados.visualizar'];
 WHEN p_tabela IN ('seller_eligibility','gm_elegibilidade','cart_elegibilidade') THEN v:=ARRAY['promocoes.visualizar','full.visualizar','qualidade.visualizar','carteiras.visualizar','dados.visualizar'];
 WHEN p_tabela LIKE 'ml_ads_%' THEN v:=ARRAY['publicidade.visualizar','resumo.visualizar','correlacoes.visualizar'];
 WHEN p_tabela='ml_questions' THEN v:=ARRAY['perguntas.visualizar'];
 WHEN p_tabela='metas_loja' THEN v:=ARRAY['metas.visualizar','resumo.visualizar'];
 WHEN p_tabela IN ('ml_market_studies','ml_trends_weekly','ml_trends_coletas','ml_trend_categorias') THEN v:=ARRAY['mercado.visualizar'];
 WHEN p_tabela='ml_listing_improvements' THEN v:=ARRAY['anuncios.visualizar','qualidade.visualizar','publicidade.visualizar'];
 WHEN p_tabela IN ('ml_accounts','ml_settings') THEN v:=ARRAY['integracoes.visualizar','resumo.visualizar','anuncios.visualizar','publicidade.visualizar','perguntas.visualizar','promocoes.visualizar','mercado.visualizar','full.visualizar'];
 WHEN p_tabela='ml_sync_tema' THEN v:=ARRAY['resumo.visualizar','reputacao.visualizar','preco.visualizar','publicidade.visualizar','promocoes.visualizar','clips.visualizar','logistica.visualizar','qualidade.visualizar','full.visualizar','metas.visualizar','correlacoes.visualizar','anuncios.visualizar','integracoes.visualizar'];
 WHEN p_tabela IN ('portfolios','portfolio_notifications','grupos') THEN v:=ARRAY['carteiras.visualizar'];
 WHEN p_tabela LIKE 'multilojas_%' OR p_tabela IN ('fin_operations','fin_costs') THEN v:=ARRAY['multilojas.visualizar'];
 WHEN p_tabela IN ('config_estimativa','benchmark_uplift_full') THEN v:=ARRAY['full.visualizar'];
 WHEN p_tabela IN ('seller_grants','gm_concessionarias') THEN v:=ARRAY['logistica.visualizar','carteiras.visualizar','multilojas.visualizar','alertas.visualizar'];
 ELSE v:=ARRAY['dados.visualizar']; END CASE;
 END IF;
 RETURN public.usuario_tem_alguma_permissao(v);
 END; $$;
REVOKE ALL ON FUNCTION public.guard_permissao_tabela(text,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.guard_permissao_tabela(text,boolean) TO authenticated,service_role;
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['sellers','sellers_pm','sellers_kpi','sellers_kpi_daily','cpp_mensal','cdp_mensal','raw_cpp_mensal','raw_cdp_mensal','live_listings','gm_live_listings','gm_elegibilidade','seller_eligibility','seller_listings_quality','meli_campaigns','metas_loja','ml_listings','ml_listings_estado','ml_anuncios','ml_questions','ml_listing_improvements','ml_market_studies','ml_trends_weekly','ml_trends_coletas','ml_trend_categorias','ml_ads_ads','ml_ads_advertisers','ml_ads_campaigns','ml_ads_estado','ml_ads_metrics_daily','ml_promotions','ml_promotion_items','ml_accounts','ml_settings','ml_sync_tema','portfolios','portfolio_notifications','grupos','multilojas_loja','multilojas_conta','multilojas_pedido','multilojas_fonte','multilojas_carga','fin_operations','fin_costs','seller_grants','gm_concessionarias','cart_base_vendedores','cart_cpp_mensal','cart_cpp_diarizado','cart_cdp_mensal','cart_cdp_diarizado','cart_elegibilidade','cart_livelistings','config_estimativa','benchmark_uplift_full','upload_logs','ingest_log','drive_ingest_log','ingestao_execucoes'] LOOP
 EXECUTE format('CREATE POLICY checklist_read ON public.%I AS RESTRICTIVE FOR SELECT TO authenticated USING (public.guard_permissao_tabela(%L,false))',t,t);
 EXECUTE format('CREATE POLICY checklist_insert ON public.%I AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (public.guard_permissao_tabela(%L,true))',t,t);
 EXECUTE format('CREATE POLICY checklist_update ON public.%I AS RESTRICTIVE FOR UPDATE TO authenticated USING (public.guard_permissao_tabela(%L,true)) WITH CHECK (public.guard_permissao_tabela(%L,true))',t,t,t);
 EXECUTE format('CREATE POLICY checklist_delete ON public.%I AS RESTRICTIVE FOR DELETE TO authenticated USING (public.guard_permissao_tabela(%L,true))',t,t);
 END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.guard_tema_ml(p_tema text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE p_tema WHEN 'vendas' THEN usuario_tem_alguma_permissao(ARRAY['resumo.visualizar','reputacao.visualizar','full.visualizar','publicidade.visualizar','correlacoes.visualizar']) WHEN 'reputacao' THEN tem_permissao('reputacao.visualizar') WHEN 'logistica' THEN tem_permissao('logistica.visualizar') WHEN 'publicidade' THEN usuario_tem_alguma_permissao(ARRAY['publicidade.visualizar','resumo.visualizar','correlacoes.visualizar']) WHEN 'qualidade' THEN tem_permissao('qualidade.visualizar') WHEN 'preco' THEN tem_permissao('preco.visualizar') WHEN 'promocoes' THEN tem_permissao('promocoes.visualizar') WHEN 'perguntas' THEN tem_permissao('perguntas.visualizar') ELSE guard_permissao_tabela('ml_sync_tema',false) END; $$;
REVOKE ALL ON FUNCTION public.guard_tema_ml(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.guard_tema_ml(text) TO authenticated,service_role;
CREATE POLICY checklist_tema ON public.ml_sync_tema AS RESTRICTIVE FOR SELECT TO authenticated USING(public.guard_tema_ml(tema));
CREATE POLICY usuarios_profiles_read ON public.profiles FOR SELECT TO authenticated USING(public.tem_permissao('usuarios.visualizar'));